function die(msg: string): never {
	console.error(`✗ ${msg}`);
	process.exit(1);
}

export function parseArgs(argv: string[]): OpenOptions {
	const options: OpenOptions = {
		port: BROWSER_DEFAULTS.port,
		url: BROWSER_DEFAULTS.url,
		urlExplicit: false,
		headless: false,
		status: false,
		minimize: true,
		park: true,
		flash: false,
		dryRun: false,
		json: false,
		clean: false,
		keepExtensions: false,
		loadTimeoutMs: 15_000,
		android: false,
		record: false,
		recordFrames: null,
		browserArgs: [],
		locale: process.env.BROWSER_LOCALE?.trim() || DEFAULT_LOCALE,
	};

	for (let i = 0; i < argv.length; i++) {
		switch (argv[i]) {
			case "--port":
				options.port = +(argv[++i] ?? die("Usage: --port <N>"));
				break;
			case "--url":
				options.url = argv[++i] ?? die("Usage: --url <url>");
				options.urlExplicit = true;
				break;
			case "--user-data":
				options.userDataDir = argv[++i] ?? die("Usage: --user-data <dir>");
				break;
			case "--clean":
				options.clean = true;
				break;
			case "--load-timeout": {
				const secs = +(argv[++i] ?? die("Usage: --load-timeout <seconds>"));
				if (!Number.isFinite(secs) || secs < 0) die("Usage: --load-timeout <seconds>");
				options.loadTimeoutMs = secs * 1000;
				break;
			}
			case "--session":
				options.session = argv[++i] ?? die("Usage: --session <name>");
				break;
			case "--binary":
				options.binary = argv[++i] ?? die("Usage: --binary <path>");
				break;
			case "--headless":
				options.headless = true;
				break;
			case "--android":
				options.android = true;
				break;
			case "--record":
				options.record = true;
				if (argv[i + 1] && !argv[i + 1].startsWith("--")) {
					const frames = +(argv[i + 1] ?? "");
					if (!Number.isInteger(frames) || frames <= 0)
						die("Usage: --record [N]");
					options.recordFrames = frames;
					i += 1;
				}
				break;
			case "--status":
				options.status = true;
				break;
			case "--load-extension":
				options.loadExtension =
					argv[++i] ?? die("Usage: --load-extension <dir>");
				break;
			case "--keep-extensions":
				options.keepExtensions = true;
				break;
			case "--browser-arg":
				options.browserArgs.push(
					argv[++i] ?? die("Usage: --browser-arg <arg>"),
				);
				break;
			case "--locale":
				options.locale = argv[++i] ?? die("Usage: --locale <bcp47>");
				break;
			case "--minimize":
				options.minimize = true;
				options.park = false;
				break;
			case "--background":
				options.minimize = true;
				options.park = true;
				break;
			case "--normal":
			case "--no-minimize":
				options.minimize = false;
				options.park = false;
				break;
			case "--flash":
				options.flash = true;
				break;
			case "--dry-run":
				options.dryRun = true;
				break;
			case "--json":
				options.json = true;
				break;
			case "--help":
				printHelp(HELP);
				process.exit(0);
			default:
				die(`Unknown option: ${argv[i]}`);
		}
	}

	if (!Number.isInteger(options.port) || options.port <= 0)
		die("Port must be a positive integer");
	if (options.userDataDir && options.clean)
		die("--user-data and --clean are mutually exclusive");
	if (
		options.recordFrames !== null &&
		(!Number.isInteger(options.recordFrames) || options.recordFrames <= 0)
	)
		die("--record must use a positive integer when a frame count is provided");

	if (
		options.url &&
		!/^(https?|ftp|about|chrome|file|data|view-source):/i.test(options.url)
	) {
		if (options.url.startsWith("//")) {
			options.url = `http:${options.url}`;
		} else if (/^[\w.-]+/.test(options.url)) {
			options.url = `http://${options.url}`;
		}
	}

	return options;
}

