edits.newText:
export function extensionArgs(
	options: Pick<OpenOptions, "loadExtension" | "keepExtensions" | "headless"> & { selectorDir?: string },
): string[] {
	const args: string[] = [];
	const dirs: string[] = [];
	if (options.loadExtension) dirs.push(options.loadExtension);
	if (options.selectorDir) dirs.push(options.selectorDir);
	if (dirs.length) args.push(`--load-extension=${dirs.join(",")}`);
	if (options.keepExtensions) return args;
	if (options.loadExtension) args.push(`--disable-extensions-except=${dirs.join(",")}`);
	else if (options.headless) {
		if (options.selectorDir) args.push(`--disable-extensions-except=${options.selectorDir}`);
		else args.push("--disable-extensions");
	}
	return args;
}

/**
 * The Dev Selector build to load: the newer of `.output/chrome-mv3` and
 * `.output/chrome-mv3-dev` under `root` (by manifest mtime). If only one
 * build exists it is used; if neither does, the error names the missing
 * build dirs so the user knows what to build.
 */
export function resolveDevSelectorDir(root: string = process.cwd()): string {
	const candidates = ["chrome-mv3", "chrome-mv3-dev"].map((name) => join(root, ".output", name));
	let best: string | undefined;
	let bestMtime = -Infinity;
	for (const dir of candidates) {
		let mtime: number;
		try {
			mtime = statSync(join(dir, "manifest.json")).mtimeMs;
		} catch {
			try {
				mtime = statSync(dir).mtimeMs;
			} catch {
				continue;
			}
		}
		if (mtime > bestMtime) {
			bestMtime = mtime;
			best = dir;
		}
	}
	if (best) return best;
	throw new Error(
		`Dev Selector build not found: ${candidates.join(" or ")} — build Dev Selector first (e.g. in .output/chrome-mv3)`,
	);
}

